class Dcs:
    """Every family of the DCS API catalog."""

    def __init__(self, client: Any) -> None:
        self._client = client

    def airbases(self) -> AirbasesCalls:
        return AirbasesCalls(self._client)

    def atmosphere(self) -> AtmosphereCalls:
        return AtmosphereCalls(self._client)

    def coalition(self) -> CoalitionCalls:
        return CoalitionCalls(self._client)

    def coord(self) -> CoordCalls:
        return CoordCalls(self._client)

    def effects(self) -> EffectsCalls:
        return EffectsCalls(self._client)

    def env(self) -> EnvCalls:
        return EnvCalls(self._client)

    def land(self) -> LandCalls:
        return LandCalls(self._client)

    def markup(self) -> MarkupCalls:
        return MarkupCalls(self._client)

    def net(self) -> NetCalls:
        return NetCalls(self._client)

    def server(self) -> ServerCalls:
        return ServerCalls(self._client)

    def sounds(self) -> SoundsCalls:
        return SoundsCalls(self._client)

    def spots(self) -> SpotsCalls:
        return SpotsCalls(self._client)

    def static_types(self) -> StaticTypesCalls:
        return StaticTypesCalls(self._client)

    def timer(self) -> TimerCalls:
        return TimerCalls(self._client)

    def unit_types(self) -> UnitTypesCalls:
        return UnitTypesCalls(self._client)

    def world(self) -> WorldCalls:
        return WorldCalls(self._client)

    def object(self, target: Target) -> ObjectCalls:
        """A DCS object (an Eid, a name, a selector message or a returned object)."""
        return ObjectCalls(self._client, target)

    def coalition_object(self, target: Target) -> CoalitionObjectCalls:
        """A DCS coalition_object (an Eid, a name, a selector message or a returned object)."""
        return CoalitionObjectCalls(self._client, target)

    def unit(self, target: Target) -> UnitCalls:
        """A DCS unit (an Eid, a name, a selector message or a returned object)."""
        return UnitCalls(self._client, target)

    def static_object(self, target: Target) -> StaticObjectCalls:
        """A DCS static_object (an Eid, a name, a selector message or a returned object)."""
        return StaticObjectCalls(self._client, target)

    def airbase(self, target: Target) -> AirbaseCalls:
        """A DCS airbase (an Eid, a name, a selector message or a returned object)."""
        return AirbaseCalls(self._client, target)

    def group(self, target: Target) -> GroupCalls:
        """A DCS group (an Eid, a name, a selector message or a returned object)."""
        return GroupCalls(self._client, target)

    def controller(self, target: Target) -> ControllerCalls:
        """A DCS controller (an Eid, a name, a selector message or a returned object)."""
        return ControllerCalls(self._client, target)

    def warehouse(self, target: Target) -> WarehouseCalls:
        """A DCS warehouse (an Eid, a name, a selector message or a returned object)."""
        return WarehouseCalls(self._client, target)

    def spot(self, target: Target) -> SpotCalls:
        """A DCS spot (an Eid, a name, a selector message or a returned object)."""
        return SpotCalls(self._client, target)
